function pathIntersections(paths, sampleDistance = 5) {
	const pathGraph = []
	for (let i = 0; i < paths.length; i++) {
		for (let j = i; j < paths.length; j++) {
			pathGraph[i] = pathGraph[i] || []
			pathGraph[j] = pathGraph[j] || []
			if (j === i) {
				pathGraph[i][j] = bezierSelfIntersections(paths[i], sampleDistance)
			} else {
				[pathGraph[i][j], pathGraph[j][i]] = bezierIntersections(paths[i], paths[j], sampleDistance)
			}
		}
	}

	const orderedIntersections = pathGraph
		.map((intersections, i) => intersections
			.reduce((acc, next) => acc.concat(next), [])
			.sort((a, b) => a.distance - b.distance)
		)

	for (const intersections of orderedIntersections) {
		for (let i = 0; i < intersections.length; i++) {
			const curr = intersections[i]
			const prev = intersections[(i - 1 + intersections.length) % intersections.length]
			const next = intersections[(i + 1) % intersections.length]
			curr.next.push(next)
			curr.prev.push(prev)
		}
	}
	const allIntersections = orderedIntersections
		.reduce((a, b) => a.concat(b), [])

	const visit = (node, under) => {
		if (node.visited) return
		node.visited = true
		node.under = under
		visit(node.other, !under)
		for (const neighbour of [...node.next, ...node.prev]) {
			visit(neighbour, !under)
		}
	}

	let _wG_4 = 0; while ((true) && ++_wG_4 < 20000) {
		const node = allIntersections.find((n) => !n.visited)
		if (!node) break
		visit(node, false)
	}

	return paths.map((path, i) => ({
		path,
		intersections: orderedIntersections[i]
	}))
}

function bezierSelfIntersections(a, sampleDistance = 5) {
	const polyA = polySample(a, sampleDistance)

	const intersections = []

	for (let i = 1; i < polyA.length; i++) {
		for (let j = i + 2; j < polyA.length; j++) {
			const intersectionPoint = lineSegmentIntersection(
				polyA[i - 1].point,
				polyA[i].point,
				polyA[j - 1].point,
				polyA[j].point,
			)
			if (!intersectionPoint) continue
			const ptA = { prev: [], next: [], path: a }
			const ptB = { prev: [], next: [], path: a }
			for (const { from, to, result } of [
				{ from: polyA[i - 1], to: polyA[i], result: ptA },
				{ from: polyA[j - 1], to: polyA[j], result: ptB },
			]) {
				const t = intersectionPoint.dist(from.point) / from.point.dist(to.point)
				const distance = lerp(from.distance, to.distance, t)
				result.distance = distance
			}
			const tangentI = a.getTangentAtLength(ptA.distance)
			const tangentJ = a.getTangentAtLength(ptB.distance)
			const dot = createVector(tangentI.x, tangentI.y).normalize().dot(
				createVector(tangentJ.x, tangentJ.y).normalize(),
			)
			ptA.other = ptB
			ptB.other = ptA
			ptA.dot = dot
			ptB.dot = dot
			intersections.push(ptA)
			intersections.push(ptB)
		}
	}

	return intersections
}

function bezierIntersections(a, b, sampleDistance = 5) {
	const polyA = polySample(a, sampleDistance)
	const polyB = polySample(b, sampleDistance)

	const intersectionsA = []
	const intersectionsB = []

	for (let i = 1; i < polyA.length; i++) {
		for (let j = 1; j < polyB.length; j++) {
			const intersectionPoint = lineSegmentIntersection(
				polyA[i - 1].point,
				polyA[i].point,
				polyB[j - 1].point,
				polyB[j].point,
			)
			if (!intersectionPoint) continue
			const ptA = { prev: [], next: [], path: a }
			const ptB = { prev: [], next: [], path: b }
			for (const { from, to, result } of [
				{ from: polyA[i - 1], to: polyA[i], result: ptA },
				{ from: polyB[j - 1], to: polyB[j], result: ptB },
			]) {
				const t = intersectionPoint.dist(from.point) / from.point.dist(to.point)
				const distance = lerp(from.distance, to.distance, t)
				result.distance = distance
			}
			const tangentI = a.getTangentAtLength(ptA.distance)
			const tangentJ = b.getTangentAtLength(ptB.distance)
			const dot = createVector(tangentI.x, tangentI.y).normalize().dot(
				createVector(tangentJ.x, tangentJ.y).normalize(),
			)
			ptA.dot = dot
			ptB.dot = dot
			ptA.other = ptB
			ptB.other = ptA
			intersectionsA.push(ptA)
			intersectionsB.push(ptB)
		}
	}

	return [intersectionsA, intersectionsB]
}

function polySample(path, sampleDistance) {
	const numSamples = Math.max(2, Math.ceil(path.getTotalLength() / sampleDistance))
	const samples = []
	for (let i = 0; i < numSamples; i++) {
		const distance = i / (numSamples - 1) * path.getTotalLength()
		const rawPoint = path.getPointAtLength(distance)
		const point = createVector(rawPoint.x, rawPoint.y)
		samples.push({ distance, point })
	}

	return samples
}

function lineSegmentIntersection(aFrom, aTo, bFrom, bTo) {
	// Bounding box check
	/*const minAX = Math.min(aFrom.x, aTo.x)
	const maxAX = Math.max(aFrom.x, aTo.x)
	const minAY = Math.min(aFrom.y, aTo.y)
	const maxAY = Math.max(aFrom.y, aTo.y)
	const minBX = Math.min(bFrom.x, bTo.x)
	const maxBX = Math.max(bFrom.x, bTo.x)
	const minBY = Math.min(bFrom.y, bTo.y)
	const maxBY = Math.max(bFrom.y, bTo.y)
	if (Math.max(minAX, minBX) > Math.min(maxAX, maxBX) || Math.max(minAY, minBY) > Math.min(maxAY, maxBY)) {
		return undefined
	}*/

  const det =
    (aTo.x - aFrom.x) * (bTo.y - bFrom.y) -
    (bTo.x - bFrom.x) * (aTo.y - aFrom.y)
  if (det === 0) {
    // Lines are parallel
    return undefined
  } else {
    const lambda =
      ((bTo.y - bFrom.y) * (bTo.x - aFrom.x) +
        (bFrom.x - bTo.x) * (bTo.y - aFrom.y)) /
      det
    const gamma =
      ((aFrom.y - aTo.y) * (bTo.x - aFrom.x) +
        (aTo.x - aFrom.x) * (bTo.y - aFrom.y)) /
      det
    if (0 < lambda && lambda < 1 && 0 < gamma && gamma < 1) {
      return aFrom.copy().add(aTo.copy().sub(aFrom).mult(lambda))
    } else {
      return undefined
    }
  }
}

